func TestValidate(t *testing.T) {
	tests := []struct {
		name       string
		cfg        *Config
		wantErrMsg string
	}{
		{
			name: "https: valid",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/ssl_cert.pem",
					CertKey:  "./testdata/ssl_key.pem",
				},
				Database: DatabaseConfig{
					URL: "localhost",
				},
			},
		},
		{
			name: "http: valid",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTP,
				},
				Database: DatabaseConfig{
					URL: "localhost",
				},
			},
		},
		{
			name: "https: empty cert_file path",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "",
					CertKey:  "./testdata/ssl_key.pem",
				},
			},
			wantErrMsg: "server.cert_file cannot be empty when using HTTPS",
		},
		{
			name: "https: empty key_file path",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/ssl_cert.pem",
					CertKey:  "",
				},
			},
			wantErrMsg: "server.cert_key cannot be empty when using HTTPS",
		},
		{
			name: "https: missing cert_file",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "foo.pem",
					CertKey:  "./testdata/ssl_key.pem",
				},
			},
			wantErrMsg: "cannot find TLS server.cert_file at \"foo.pem\"",
		},
		{
			name: "https: missing key_file",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/ssl_cert.pem",
					CertKey:  "bar.pem",
				},
			},
			wantErrMsg: "cannot find TLS server.cert_key at \"bar.pem\"",
		},
		{
			name: "db: missing protocol",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTP,
				},
				Database: DatabaseConfig{},
			},
			wantErrMsg: "database.protocol cannot be empty",
		},
		{
			name: "db: missing host",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTP,
				},
				Database: DatabaseConfig{
					Protocol: DatabaseSQLite,
				},
			},
			wantErrMsg: "database.host cannot be empty",
		},
		{
			name: "db: missing name",
			cfg: &Config{
				Server: ServerConfig{
					Protocol: HTTP,
				},
				Database: DatabaseConfig{
					Protocol: DatabaseSQLite,
					Host:     "localhost",
				},
			},
			wantErrMsg: "database.name cannot be empty",
		},
	}

	for _, tt := range tests {
		var (
			cfg        = tt.cfg
			wantErrMsg = tt.wantErrMsg
		)

		t.Run(tt.name, func(t *testing.T) {
			err := cfg.validate()

			if wantErrMsg != "" {
				require.Error(t, err)
				assert.EqualError(t, err, wantErrMsg)
				return
			}

			require.NoError(t, err)
		})
	}
}

